package net.officefloor.hq.app.period;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the body: who closes the period. */
public class ValidatePeriodClose {
    public void validate(@RequestBody PeriodCloseRequest request, Out<PeriodCloseRequest> body) {
        body.set(new PeriodCloseRequest(request == null || request.by() == null ? "" : request.by().trim()));
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

/** Loads a period of the sheet by id; one not on the sheet is refused. */
public class LoadPeriod {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("periodId") String periodId,
            PeriodRepository periods, Out<Period> period) throws InvalidPeriodException {
        Period found;
        try {
            found = periods.find(sheetId.trim(), Long.parseLong(periodId.trim()));
        } catch (NumberFormatException e) {
            found = null;
        }
        if (found == null) {
            throw new InvalidPeriodException("No period " + periodId);
        }
        period.set(found);
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimDue;
import net.officefloor.hq.app.claim.ClaimLogLine;
import net.officefloor.hq.app.claim.ClaimLogRepository;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.claim.LateCharge;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Closes an open period, fixing its due-total as it is now: the figures (each due as shown now, with its late charge)
 *  of the claims whose date falls in it and that counted by the status each had at the end of the period's last day,
 *  as its status log records it (a claim added after it does not count), the live rules otherwise applying (a
 *  person's claims OPEN or PENDING now and dated within a hold of theirs, not bound by a statement, do not, nor do deferred
 *  claims), added up (skipping n/a). Each person's own due-total for the period is fixed
 *  too, for every person on the sheet; the period's is the sum of theirs. Closing a period already closed is refused, and so is closing by a role the sheet's close permission does not allow. */
public class ClosePeriod {
    public void close(@Val Period period, @Val PeriodCloseRequest request, PeriodRepository periods,
            ClaimRepository claims, PersonRepository people, RateRepository rates, SettingRepository settings,
            SheetRepository sheets, ClaimLogRepository log, RoleRepository roles,
            Out<PeriodClose> closed)
            throws InvalidPeriodException {
        if (!settings.permits(period.sheetId(), "close", roles.roleOf(period.sheetId(), request.by()))) {
            throw new InvalidPeriodException("The sheet's permission does not let this user close a period");
        }
        if (period.closed()) {
            throw new InvalidPeriodException("The period " + period.name() + " is already closed");
        }
        Map<Long, Person> byId = people.list(period.sheetId()).stream()
                .collect(Collectors.toMap(Person::id, (p) -> p));
        Map<Long, List<ClaimLogLine>> logs = log.bySheet(period.sheetId());
        LateCharge late = LateCharge.of(period.sheetId(), sheets, settings, claims);
        Map<Long, BigDecimal> perPerson = new LinkedHashMap<>();
        for (Long id : byId.keySet()) {
            perPerson.put(id, BigDecimal.ZERO.setScale(2));
        }
        for (Claim c : claims.list(period.sheetId())) {
            Person person = byId.get(c.personId());
            if (c.date().isBefore(period.from()) || c.date().isAfter(period.to())) {
                continue;
            }
            ClaimStatus status = ClaimDue.statusAsOf(logs.getOrDefault(c.id(), List.of()), period.to());
            if (status == null || !ClaimDue.counts(ClaimDue.withStatus(c, status))
                    || (ClaimDue.isOpen(c) && !ClaimDue.bound(c) && person != null && person.heldOn(c.date()))
                    || ClaimDue.deferred(c, late.today())) {
                continue;
            }
            BigDecimal figure = person == null ? c.due() : late.add(c, ClaimDue.figure(c, person.gradeOn(c.date()), rates, settings.floor(c.sheetId(), c.date()), late.rounding()));
            if (figure != null) {
                perPerson.merge(c.personId(), figure, BigDecimal::add);
            }
        }
        BigDecimal total = perPerson.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
        if (!periods.close(period, total)) {
            throw new InvalidPeriodException("The period " + period.name() + " is already closed");
        }
        periods.fixPersonTotals(period, perPerson);
        closed.set(new PeriodClose(request.by(), total));
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;

/** Writes PERIOD_CLOSED to the audit file once the period is closed, with the due-total it fixed. */
public class RecordPeriodClosed {
    public void record(@Val Period period, @Val PeriodClose closed, Audit audit) {
        audit.record("PERIOD_CLOSED sheet=" + period.sheetId() + " by=" + closed.by() + " period=" + period.name()
                + " total=" + closed.total().toPlainString());
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;

/** A period being closed: who closes it, and (once closed) the due-total it fixed. */
public record PeriodClose(String by, BigDecimal total) {
}
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

public class ApplyToday {
    public void apply(@Val Sheet sheet, @Val LocalDate today, Out<Sheet> changed) {
        changed.set(new Sheet(sheet.id(), today));
    }
}
package net.officefloor.hq.app.sheet;

import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupBefore;
import net.officefloor.plugin.variable.Val;

/** Changing the sheet's today writes no line of its own, only the figures it moved (see Rollup). */
public class RecordTodayChanged {
    public void record(@Val Sheet sheet, @Val TodayBy by, @Val RollupBefore before, Rollup rollup) {
        rollup.record(sheet.id(), by.by(), before);
    }
}
package net.officefloor.hq.app.sheet;

import net.officefloor.plugin.variable.Val;

public class SaveSheet {
    public void save(@Val Sheet sheet, SheetRepository sheets) {
        sheets.saveToday(sheet.id(), sheet.today());
    }
}

