public record PeriodClose(String by, BigDecimal total) {
}
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

public class ApplyToday {
    public void apply(@Val Sheet sheet, @Val LocalDate today, Out<Sheet> changed) {
        changed.set(new Sheet(sheet.id(), today));
    }
}
package net.officefloor.hq.app.sheet;

import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupBefore;
import net.officefloor.plugin.variable.Val;

/** Changing the sheet's today writes no line of its own, only the figures it moved (see Rollup). */
public class RecordTodayChanged {
    public void record(@Val Sheet sheet, @Val TodayBy by, @Val RollupBefore before, Rollup rollup) {
        rollup.record(sheet.id(), by.by(), before);
    }
}
package net.officefloor.hq.app.sheet;

import net.officefloor.plugin.variable.Val;

public class SaveSheet {
    public void save(@Val Sheet sheet, SheetRepository sheets) {
        sheets.saveToday(sheet.id(), sheet.today());
    }
}

